import{_ as e,o as t,c as o,a2 as c}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"NotEnoughAccuracy","description":"","frontmatter":{"title":"NotEnoughAccuracy","order":9},"headers":[],"relativePath":"mods/not-enough-accuracy.md","filePath":"mods/not-enough-accuracy.md","lastUpdated":1786957039000}'),r={name:"mods/not-enough-accuracy.md"};function s(i,a,n,l,u,h){return t(),o("div",null,[...a[0]||(a[0]=[c(`<h1 id="notenoughaccuracy" tabindex="-1">NotEnoughAccuracy <a class="header-anchor" href="#notenoughaccuracy" aria-label="Permalink to &quot;NotEnoughAccuracy&quot;">​</a></h1><blockquote><p>Think XPerfect still isn&#39;t strict enough? <strong>Not Enough Accuracy (NEAcc / NEA)</strong> takes every millisecond into calculation, giving you the most precise gameplay accuracy.</p><p>Project: <a href="https://github.com/adofaiex/NotEnoughAccuracy" target="_blank" rel="noreferrer">https://github.com/adofaiex/NotEnoughAccuracy</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>This Mod does not affect ADOFAI&#39;s judgment!</strong> It is just another way of calculating accuracy.</p></div><h2 id="accuracy-algorithm" tabindex="-1">Accuracy Algorithm <a class="header-anchor" href="#accuracy-algorithm" aria-label="Permalink to &quot;Accuracy Algorithm&quot;">​</a></h2><h3 id="tiles-total-count" tabindex="-1">Tiles (total count) <a class="header-anchor" href="#tiles-total-count" aria-label="Permalink to &quot;Tiles (total count)&quot;">​</a></h3><p>Total tiles = VE + EP + PP + LP + VL + FailMiss − Midspins, where each midspin counts as only one tile.</p><h3 id="per-tile-score" tabindex="-1">Per-Tile Score <a class="header-anchor" href="#per-tile-score" aria-label="Permalink to &quot;Per-Tile Score&quot;">​</a></h3><p>Only the judgment that pushes you forward is considered:</p><ul><li>Missed tile in no-fail mode: <code>-100</code></li><li>Otherwise: <code>max(100 − |x|, 0)</code>, where <code>x</code> is the <strong>millisecond deviation</strong> from the precise timing of the tile (regardless of the actual judgment)</li></ul><p>I.e.: base score per tile is 100, each millisecond of deviation costs 1 point (down to 0); misses in no-fail mode score -100.</p><h3 id="extra-penalties" tabindex="-1">Extra Penalties <a class="header-anchor" href="#extra-penalties" aria-label="Permalink to &quot;Extra Penalties&quot;">​</a></h3><ul><li>Each TooEarly / TooLate: extra <strong>−50</strong></li><li>Each FailOverload: extra <strong>−100</strong></li></ul><h3 id="total-accuracy" tabindex="-1">Total Accuracy <a class="header-anchor" href="#total-accuracy" aria-label="Permalink to &quot;Total Accuracy&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TotalScores = sum of all scores above (can be negative)</span></span>
<span class="line"><span>NEAccuracy% = TotalScores / Tiles</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>GPL v3</p>`,16)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
